#[test]
fn hashes_match_python() {
    for (m, s256, s512) in HASH {
        let m = hex(m);
        assert_eq!(to_hex(&sha256::digest(&m)), *s256, "sha256 len {}", m.len());
        assert_eq!(to_hex(&sha512::digest(&m)), *s512, "sha512 len {}", m.len());
    }
}

#[test]
fn hmac_matches_python() {
    for (k, m, tag) in HMAC {
        assert_eq!(to_hex(&hmac::hmac_sha256(&hex(k), &hex(m))), *tag);
    }
}

#[test]
fn hkdf_matches_python() {
    for (salt, ikm, info, okm) in HKDF {
        let prk = hkdf::extract(&hex(salt), &hex(ikm));
        let mut out = vec![0u8; okm.len() / 2];
        hkdf::expand(&prk, &hex(info), &mut out).unwrap();
        assert_eq!(to_hex(&out), *okm);
    }
    let prk = hkdf::extract(b"", b"x");
    assert!(hkdf::expand(&prk, b"", &mut vec![0u8; 255 * 32 + 1]).is_err());
}

#[test]
fn aead_matches_python() {
    for (k, n, a, p, sealed) in AEAD {
        let key: [u8; 32] = hex(k).try_into().unwrap();
        let nonce: [u8; 12] = hex(n).try_into().unwrap();
        let (aad, pt) = (hex(a), hex(p));
        assert_eq!(to_hex(&aead::seal(&key, &nonce, &aad, &pt)), *sealed);
        assert_eq!(aead::open(&key, &nonce, &aad, &hex(sealed)).unwrap(), pt);
    }
}
